// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes calldata _data) public {
        vm.assume(callee != address(0));
        vm.assume(callee != address(c));
        vm.assume(_data.length >= 4);
        Reverter r = new Reverter();
        bool ok;
        try c.forward(address(r), _data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
